import{_ as s,c as n,aU as l,a as t}from"./chunks/framework.DIXiA2XH.js";const u=JSON.parse('{"title":"服务发布","description":"","frontmatter":{},"headers":[],"relativePath":"note/server/docker/服务发布.md","filePath":"note/server/docker/服务发布.md","lastUpdated":1776608627000}'),e={name:"note/server/docker/服务发布.md"};function r(i,a,o,p,d,c){return t(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="服务发布" tabindex="-1">服务发布 <a class="header-anchor" href="#服务发布" aria-label="Permalink to &quot;服务发布&quot;">​</a></h1><p>我也不知道叫啥了，随便起个名字吧。。。</p><p>这里普及一下真正的工作中发布的一些类型。</p><h2 id="🆚-三者核心区别总结" tabindex="-1">🆚 三者核心区别总结 <a class="header-anchor" href="#🆚-三者核心区别总结" aria-label="Permalink to &quot;🆚 三者核心区别总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>滚动更新</th><th>蓝绿部署</th><th>金丝雀发布</th></tr></thead><tbody><tr><td><strong>资源占用</strong></td><td>1x（最少）</td><td>2x（最多）</td><td>~1.2x（按比例）</td></tr><tr><td><strong>发布速度</strong></td><td>慢（逐个替换）</td><td>极快（瞬间切换）</td><td>渐进（几分钟到几小时）</td></tr><tr><td><strong>回滚速度</strong></td><td>慢（再滚一遍）</td><td>极快（切回）</td><td>极快（关掉金丝雀流量）</td></tr><tr><td><strong>风险范围</strong></td><td>高（逐步扩散）</td><td>低（全有或全无）</td><td><strong>极低（仅小部分用户）</strong></td></tr><tr><td><strong>是否需要额外工具</strong></td><td>否（K8s 原生）</td><td>是（需 LB 切换）</td><td>是（需流量控制）</td></tr><tr><td><strong>适合场景</strong></td><td>内部工具、低风险变更</td><td>关键业务、大版本升级</td><td>高频发布、A/B 测试</td></tr></tbody></table><h2 id="🧩-假设前提-统一上下文" tabindex="-1">🧩 假设前提（统一上下文） <a class="header-anchor" href="#🧩-假设前提-统一上下文" aria-label="Permalink to &quot;🧩 假设前提（统一上下文）&quot;">​</a></h2><ul><li>你有一个 Go Web 服务 <code>user-api</code>，当前运行 <strong>v1.0 版本</strong></li><li>生产环境有 <strong>5 台服务器（或 5 个 Pod）</strong>，都运行 v1.0</li><li>现在要上线 <strong>v1.1 版本</strong></li><li>用户通过负载均衡器（如 Nginx、云厂商 SLB、K8s Service）访问服务</li></ul><blockquote><p>💡 为了简化，我们以 <strong>Kubernetes Pod</strong> 为例（但逻辑同样适用于物理机/虚拟机集群）。</p></blockquote><h2 id="滚动更新-——-边换边跑" tabindex="-1">滚动更新 —— “边换边跑” <a class="header-anchor" href="#滚动更新-——-边换边跑" aria-label="Permalink to &quot;滚动更新 —— “边换边跑”&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">像修路，一边拆旧砖一边铺新砖，路上一直能走人，但如果新砖质量差，整条路慢慢都坏了。</p><p></p></div><p>这是 Kubernetes 的 <strong>默认发布策略</strong>。</p><h3 id="🔧-过程" tabindex="-1">🔧 过程： <a class="header-anchor" href="#🔧-过程" aria-label="Permalink to &quot;🔧 过程：&quot;">​</a></h3><ol><li>K8s 开始逐步替换旧 Pod： <ul><li>先启动 <strong>1 个 v1.1 Pod</strong></li><li>等它就绪后，<strong>销毁 1 个 v1.0 Pod</strong></li><li>再启动第 2 个 v1.1，销毁第 2 个 v1.0……</li></ul></li><li>整个过程保持 <strong>至少 4 个 Pod 在线</strong>（可配置）</li><li>最终 5 个 Pod 全部变成 v1.1</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间线：</span></span>
<span class="line"><span>[ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]  ← 初始</span></span>
<span class="line"><span>[ v1.1 ][ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]  ← 启动1个新，未删旧（共6个）</span></span>
<span class="line"><span>[ v1.1 ][ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]  ← 删除1个旧（回到5个）</span></span>
<span class="line"><span>[ v1.1 ][ v1.1 ][ v1.0 ][ v1.0 ][ v1.0 ]  ← 继续...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ]  ← 完成</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="✅-优点" tabindex="-1">✅ 优点： <a class="header-anchor" href="#✅-优点" aria-label="Permalink to &quot;✅ 优点：&quot;">​</a></h3><ul><li>资源利用率高（不需要双倍机器）</li><li>服务不中断</li></ul><h3 id="❌-缺点" tabindex="-1">❌ 缺点： <a class="header-anchor" href="#❌-缺点" aria-label="Permalink to &quot;❌ 缺点：&quot;">​</a></h3><ul><li><strong>一旦 v1.1 有 bug，会逐步扩散到所有用户</strong></li><li>回滚慢（要再滚一遍回 v1.0）</li></ul><blockquote><p>⚠️ 如果 v1.1 有内存泄漏，可能在替换到第 3 个时系统就崩了。</p></blockquote><p>注意！！！ 这里的重点在于，我们无法精准控制pod的发布，只能等它一个一个的发布完成</p><h2 id="蓝绿部署-——-建好再切" tabindex="-1">蓝绿部署 —— “建好再切” <a class="header-anchor" href="#蓝绿部署-——-建好再切" aria-label="Permalink to &quot;蓝绿部署  —— “建好再切”&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">像建新桥。先在旁边建一座新桥，验收合格后，交警一声令下，所有车改走新桥，旧桥封闭。</p><p></p></div><h3 id="🔧-过程-1" tabindex="-1">🔧 过程： <a class="header-anchor" href="#🔧-过程-1" aria-label="Permalink to &quot;🔧 过程：&quot;">​</a></h3><ol><li><strong>先完整部署一套 v1.1 环境</strong>（另外 5 台机器 / 5 个 Pod），和 v1.0 <strong>完全隔离</strong><ul><li>此时：v1.0（5台） + v1.1（5台） = <strong>总共 10 台机器</strong></li></ul></li><li>测试 v1.1 环境没问题后，<strong>瞬间切换流量</strong>： <ul><li>负载均衡器从指向 “蓝组（v1.0）” → 改为指向 “绿组（v1.1）”</li></ul></li><li>确认稳定后，<strong>下线 v1.0 的 5 台机器</strong></li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段1（发布前）：</span></span>
<span class="line"><span>LB → [ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段2（部署新版本）：</span></span>
<span class="line"><span>LB → [ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]   ← 用户还在用</span></span>
<span class="line"><span>      [ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ]   ← 新版本待命（无流量）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段3（切换瞬间）：</span></span>
<span class="line"><span>LB → [ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ]   ← 所有用户立刻用新版本</span></span>
<span class="line"><span>      [ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]   ← 准备下线</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="✅-优点-1" tabindex="-1">✅ 优点： <a class="header-anchor" href="#✅-优点-1" aria-label="Permalink to &quot;✅ 优点：&quot;">​</a></h3><ul><li><strong>切换极快</strong>（秒级）</li><li><strong>回滚极快</strong>（改回 LB 指向即可）</li><li>用户体验一致（不会有人用 v1.0、有人用 v1.1）</li></ul><h3 id="❌-缺点-1" tabindex="-1">❌ 缺点： <a class="header-anchor" href="#❌-缺点-1" aria-label="Permalink to &quot;❌ 缺点：&quot;">​</a></h3><ul><li><strong>需要双倍资源</strong>（成本高）</li><li>数据库变更必须<strong>向后兼容</strong>（因为切换前后 v1.0/v1.1 都可能读写 DB）</li></ul><hr><h2 id="金丝雀发布-互联网公司主流" tabindex="-1">金丝雀发布 （互联网公司主流） <a class="header-anchor" href="#金丝雀发布-互联网公司主流" aria-label="Permalink to &quot;金丝雀发布 （互联网公司主流）&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">像新药试验。先给 5% 的病人试用，观察副作用，没问题再推广给所有人。</p><p></p></div><h3 id="🔧-过程-2" tabindex="-1">🔧 过程： <a class="header-anchor" href="#🔧-过程-2" aria-label="Permalink to &quot;🔧 过程：&quot;">​</a></h3><ol><li><strong>只部署 1 个 v1.1 Pod</strong>（其他 4 个仍是 v1.0）</li><li><strong>配置负载均衡器：95% 流量 → v1.0，5% 流量 → v1.1</strong></li><li>观察 v1.1 的监控指标（错误率、延迟、CPU） <ul><li>如果正常 → 逐步增加比例（比如 20% → 50% → 100%）</li><li>如果异常 → <strong>立即把 5% 流量切回 v1.0</strong>，v1.1 下线</li></ul></li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始：</span></span>
<span class="line"><span>LB → [ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>金丝雀阶段（5% 流量）：</span></span>
<span class="line"><span>LB → 95% → [ v1.0 ][ v1.0 ][ v1.0 ][ v1.0 ]</span></span>
<span class="line"><span>     5%  → [ v1.1 ]   ← 只有1个新实例</span></span>
<span class="line"><span></span></span>
<span class="line"><span>观察 OK 后（比如升到 50%）：</span></span>
<span class="line"><span>LB → 50% → [ v1.0 ][ v1.0 ]</span></span>
<span class="line"><span>     50% → [ v1.1 ][ v1.1 ][ v1.1 ]   ← 扩容 v1.1 到3个</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终全量：</span></span>
<span class="line"><span>LB → [ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ][ v1.1 ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><blockquote><p>📌 注意：金丝雀的 Pod 数量不固定，关键是<strong>流量比例</strong>。</p></blockquote><h3 id="✅-优点-2" tabindex="-1">✅ 优点： <a class="header-anchor" href="#✅-优点-2" aria-label="Permalink to &quot;✅ 优点：&quot;">​</a></h3><ul><li><strong>风险最小</strong>：最多只有 5% 用户受影响</li><li><strong>真实环境验证</strong>：不是测试环境，是生产流量！</li><li><strong>支持自动化决策</strong>（如“错误率 &lt; 0.1% 才继续”）</li></ul><h3 id="❌-缺点-2" tabindex="-1">❌ 缺点： <a class="header-anchor" href="#❌-缺点-2" aria-label="Permalink to &quot;❌ 缺点：&quot;">​</a></h3><ul><li>配置复杂（需要智能 LB 或 Service Mesh）</li><li>用户体验可能不一致（同一用户刷新可能看到不同版本）</li><li>需要完善的监控体系</li></ul><p>当你学到 Argo Rollouts 或 Istio 时，就能轻松实现自动化金丝雀发布！</p><h2 id="pod-是什么-和-docker-容器是什么关系" tabindex="-1">Pod 是什么？和 Docker 容器是什么关系？ <a class="header-anchor" href="#pod-是什么-和-docker-容器是什么关系" aria-label="Permalink to &quot;Pod 是什么？和 Docker 容器是什么关系？&quot;">​</a></h2><h3 id="✅-简单说" tabindex="-1">✅ 简单说： <a class="header-anchor" href="#✅-简单说" aria-label="Permalink to &quot;✅ 简单说：&quot;">​</a></h3><blockquote><p><strong>Pod 是 Kubernetes 的最小调度单位，它“包含”一个或多个紧密耦合的容器（通常是 1 个）。</strong></p></blockquote><h3 id="📦-具体解释" tabindex="-1">📦 具体解释： <a class="header-anchor" href="#📦-具体解释" aria-label="Permalink to &quot;📦 具体解释：&quot;">​</a></h3><ul><li>一个 <strong>Pod ≈ 一个“逻辑主机”</strong>，里面可以跑多个容器（比如主应用 + 日志收集 sidecar）</li><li>但在 <strong>90%+ 的 Web 场景中，一个 Pod 只包含 1 个应用容器</strong>（比如你的 Go 程序）</li><li>所以你可以<strong>暂时理解为：1 个 Pod ≈ 1 个 Docker 容器</strong>（但技术上 Pod 是容器的“包装壳”）</li></ul><blockquote><p>💡 类比：</p><ul><li>Docker 容器 = 一个工人</li><li>Pod = 一个“工位”，通常只坐一个工人，但也可以坐两个（比如工人 + 助手）</li></ul></blockquote><p>Kubernetes 不直接管理容器，而是管理 <strong>Pod</strong>。当你写 <code>Deployment</code>，其实是告诉 K8s：“我要 5 个这样的 Pod”。</p><h2 id="滚动更新-vs-金丝雀发布的根本区别-重点" tabindex="-1">滚动更新 vs 金丝雀发布的根本区别（重点！） <a class="header-anchor" href="#滚动更新-vs-金丝雀发布的根本区别-重点" aria-label="Permalink to &quot;滚动更新 vs 金丝雀发布的根本区别（重点！）&quot;">​</a></h2><blockquote><p>“两者都是一样的机器数量，都是让其中一个机器更新成 v1.1，每个用户都有机会访问到 v1.1”</p></blockquote><p><strong>这个理解在“结果上看”似乎一样，但背后的机制、目的和控制能力完全不同！</strong></p><p>我们用同一个例子深挖：</p><hr><h3 id="🧪-场景重设" tabindex="-1">🧪 场景重设 <a class="header-anchor" href="#🧪-场景重设" aria-label="Permalink to &quot;🧪 场景重设&quot;">​</a></h3><ul><li>当前：5 个 Pod 运行 <strong>v1.0</strong></li><li>目标：上线 <strong>v1.1</strong></li><li>负载均衡器（如 K8s Service）会把请求<strong>平均分发</strong>给所有健康 Pod</li></ul><hr><h3 id="🔄-滚动更新-rolling-update-——-强制替换-无法控制流量" tabindex="-1">🔄 滚动更新（Rolling Update）—— <strong>“强制替换，无法控制流量”</strong> <a class="header-anchor" href="#🔄-滚动更新-rolling-update-——-强制替换-无法控制流量" aria-label="Permalink to &quot;🔄 滚动更新（Rolling Update）—— **“强制替换，无法控制流量”**&quot;">​</a></h3><h4 id="关键特征" tabindex="-1">关键特征： <a class="header-anchor" href="#关键特征" aria-label="Permalink to &quot;关键特征：&quot;">​</a></h4><ul><li><strong>K8s 自动、连续地替换 Pod</strong>，直到全部更新完毕</li><li><strong>所有新 Pod 都会被加入 Service 的负载均衡池</strong></li><li><strong>你无法控制“多少流量”打到 v1.1</strong></li></ul><h4 id="实际过程" tabindex="-1">实际过程： <a class="header-anchor" href="#实际过程" aria-label="Permalink to &quot;实际过程：&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Step 1: 启动 1 个 v1.1 Pod → 现在有 6 个 Pod（5 v1.0 + 1 v1.1）</span></span>
<span class="line"><span>        Service 会把 ~1/6 ≈ 16.7% 的流量打给 v1.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 2: 删除 1 个 v1.0 Pod → 现在 5 个 Pod（4 v1.0 + 1 v1.1）</span></span>
<span class="line"><span>        流量比例变成 20% → v1.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 3: 启动第 2 个 v1.1 → 6 个 Pod（4 v1.0 + 2 v1.1）→ 33% 流量到 v1.1</span></span>
<span class="line"><span>Step 4: 删除 1 个 v1.0 → 5 个 Pod（3 v1.0 + 2 v1.1）→ 40% 流量...</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Step N: 全部变成 v1.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h4 id="❗-问题在哪" tabindex="-1">❗ 问题在哪？ <a class="header-anchor" href="#❗-问题在哪" aria-label="Permalink to &quot;❗ 问题在哪？&quot;">​</a></h4><ul><li><strong>你无法暂停</strong>！K8s 会自动继续下一步。</li><li><strong>你无法限制 v1.1 的流量比例</strong>（比如“只让 5% 用户试用”）。</li><li><strong>一旦 v1.1 有问题，错误会随着更新进度扩散</strong>（从 16% → 33% → 50%...），直到你手动暂停或回滚。</li></ul><blockquote><p>🚨 <strong>滚动更新的本质是“部署策略”，不是“流量控制策略”</strong>。</p></blockquote><hr><h3 id="🐤-金丝雀发布-canary-——-我主动控制-只放少量流量" tabindex="-1">🐤 金丝雀发布（Canary）—— <strong>“我主动控制，只放少量流量”</strong> <a class="header-anchor" href="#🐤-金丝雀发布-canary-——-我主动控制-只放少量流量" aria-label="Permalink to &quot;🐤 金丝雀发布（Canary）—— **“我主动控制，只放少量流量”**&quot;">​</a></h3><h4 id="关键特征-1" tabindex="-1">关键特征： <a class="header-anchor" href="#关键特征-1" aria-label="Permalink to &quot;关键特征：&quot;">​</a></h4><ul><li><strong>你明确部署 1 个（或少量）v1.1 Pod</strong></li><li><strong>但通过流量规则，强制只有 5% 的请求能到达它</strong></li><li><strong>其余 95% 的请求仍然只打给 v1.0 Pod（即使 v1.1 已经就绪！）</strong></li></ul><h4 id="✅-你能做什么" tabindex="-1">✅ 你能做什么？ <a class="header-anchor" href="#✅-你能做什么" aria-label="Permalink to &quot;✅ 你能做什么？&quot;">​</a></h4><ul><li><strong>暂停在 5%</strong>，观察 1 小时、1 天</li><li><strong>如果监控发现错误率飙升，立刻删掉金丝雀 Ingress，100% 流量切回 v1.0</strong></li><li><strong>如果稳定，手动把 canary-weight 改成 20 → 50 → 100</strong></li></ul><blockquote><p>🎯 <strong>金丝雀的核心是“流量比例可控 + 人工/自动决策”</strong></p></blockquote><h2 id="🆚-根本区别总结-一句话" tabindex="-1">🆚 根本区别总结（一句话） <a class="header-anchor" href="#🆚-根本区别总结-一句话" aria-label="Permalink to &quot;🆚 根本区别总结（一句话）&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>滚动更新</th><th>金丝雀发布</th></tr></thead><tbody><tr><td><strong>控制对象</strong></td><td>控制 <strong>Pod 数量</strong>（部署层面）</td><td>控制 <strong>用户流量比例</strong>（网络层面）</td></tr><tr><td><strong>能否暂停？</strong></td><td>❌ 不能（除非手动干预）</td><td>✅ 能（停在 5% 观察）</td></tr><tr><td><strong>流量比例</strong></td><td>由 Pod 数量决定（不可控）</td><td>由你设定（精确控制）</td></tr><tr><td><strong>目标</strong></td><td>完成部署</td><td><strong>验证新版本稳定性</strong></td></tr></tbody></table>`,73)])])}const h=s(e,[["render",r]]);export{u as __pageData,h as default};
